import{_ as s,o as a,c as i,a2 as t}from"./chunks/framework.ChTAMbUy.js";const c=JSON.parse('{"title":"Labs","description":"","frontmatter":{},"headers":[],"relativePath":"1.9/labs/index.md","filePath":"versions/1.9/labs/index.md","lastUpdated":1791568428000}'),n={name:"1.9/labs/index.md"};function o(r,e,l,h,p,d){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="labs" tabindex="-1">Labs <a class="header-anchor" href="#labs" aria-label="Permalink to &quot;Labs&quot;">​</a></h1><p>Labs are browser-based development environments with access to the compute resources, storage, credentials, and platform tools available in your workspace.</p><div class="info custom-block"><p class="custom-block-title">Kubeflow Notebooks documentation</p><p>Upstream reference: <a href="https://www.kubeflow.org/docs/components/notebooks/" target="_blank" rel="noreferrer">Kubeflow Notebooks documentation</a></p></div><p>You can work in a Lab without setting up a local development environment first. From a Lab, you reach other prokube tools programmatically through <code>kubectl</code>, SDKs, CLIs, and APIs. For example, you can launch pipelines, run hyperparameter tuning or distributed computing experiments, develop MCP servers, and test agent workflows.</p><p>In addition to preconfigured <a href="./jupyterlab.html">JupyterLab</a>, <a href="./vscode.html">VS Code</a>, and <a href="./rstudio.html">RStudio</a> images, Labs support AI-assisted coding: GitHub Copilot in VS Code, and <a href="./opencode.html">OpenCode</a> as a dedicated coding agent.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/labs/labs-overview.png" alt="Labs overview" loading="lazy"></p><h2 id="when-to-use-labs" tabindex="-1">When to Use Labs <a class="header-anchor" href="#when-to-use-labs" aria-label="Permalink to &quot;When to Use Labs&quot;">​</a></h2><ul><li>You want a browser IDE with workspace storage and credentials already set up.</li><li>You want coding agents to change code in the workspace instead of on your machine, and keep running when your laptop is closed or disconnected.</li><li>You want to experiment on the same CPUs, GPUs, and volumes that production workloads use.</li><li>You want to test platform integrations before packaging them for repeatable use.</li></ul><h2 id="available-environments" tabindex="-1">Available Environments <a class="header-anchor" href="#available-environments" aria-label="Permalink to &quot;Available Environments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Environment</th><th>Typical use</th></tr></thead><tbody><tr><td><a href="./jupyterlab.html">JupyterLab</a></td><td>Python notebooks, data exploration, visualization, quick experiments</td></tr><tr><td><a href="./vscode.html">VS Code</a></td><td>Browser-based IDE workflows and local VS Code attachment to running notebook pods</td></tr><tr><td><a href="./rstudio.html">RStudio</a></td><td>R notebooks, statistics workflows, and R package based analysis</td></tr><tr><td><a href="./opencode.html">OpenCode</a></td><td>Agent-assisted coding sessions inside a lab workspace</td></tr><tr><td><a href="./custom_notebooks.html">Custom Notebooks</a></td><td>Custom images and web servers for specialized applications</td></tr></tbody></table><h2 id="how-labs-work" tabindex="-1">How Labs Work <a class="header-anchor" href="#how-labs-work" aria-label="Permalink to &quot;How Labs Work&quot;">​</a></h2><p>Labs are built on <a href="https://www.kubeflow.org/docs/components/notebooks/" target="_blank" rel="noreferrer">Kubeflow Notebooks</a> and run inside your <a href="./../platform/workspaces.html">prokube workspace</a>. Each Lab gets its own <a href="https://kubernetes.io/docs/concepts/workloads/pods/" target="_blank" rel="noreferrer">Kubernetes Pod</a>, resource limits, and mounted storage.</p><p>prokube provides curated <code>pk-*</code> images with tools such as <code>rclone</code> and Docker Buildx preinstalled, mounts the workspace volume as the Lab home directory, and makes workspace settings such as the file storage configuration available inside the Lab.</p><h2 id="workspaces" tabindex="-1">Workspaces <a class="header-anchor" href="#workspaces" aria-label="Permalink to &quot;Workspaces&quot;">​</a></h2><p>Labs run in the currently selected workspace. Most users have a personal workspace, and can also be granted access to shared workspaces for team projects.</p><p>The active workspace determines which namespace, storage, credentials, and access rules the Lab uses. When you have access to multiple workspaces, select the workspace before launching a Lab.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/labs/labs-workspace-selection.png" alt="Workspace selection" loading="lazy"></p><div class="warning custom-block"><p class="custom-block-title">Secrets are workspace-visible</p><p>Each workspace has its own Kubernetes namespace. Workspace owners and edit contributors can read every Kubernetes <code>Secret</code> in that namespace, whether a workload uses it or someone created it by hand. View contributors cannot read <code>Secret</code>s.</p><p>Do not put personal access tokens, admin credentials, cloud root keys, or other broad credentials into a workspace that other people can access. For team work, use a shared workspace with credentials intended for that team and workload.</p></div><p>See <a href="./../platform/workspaces.html">Workspaces</a> for access levels and shared workspace behavior.</p><h2 id="launch-options" tabindex="-1">Launch Options <a class="header-anchor" href="#launch-options" aria-label="Permalink to &quot;Launch Options&quot;">​</a></h2><p>All Lab types share the same launch options:</p><ul><li><strong>Image</strong>: selects the IDE, language stack, preinstalled packages, and system tools.</li><li><strong>Compute resources</strong>: CPU, memory, and GPU for the Lab pod.</li><li><strong>Storage</strong>: the workspace volume, plus optional data volumes for shared datasets or larger working directories. See <a href="#persistence-and-package-installation">Persistence and Package Installation</a> for what survives restarts and how volumes can be shared.</li><li><strong>Configurations</strong> and <strong>Security options</strong>: administrator-provided pod settings. See <a href="#advanced-configuration">Advanced Configuration</a>.</li></ul><h2 id="managing-labs" tabindex="-1">Managing Labs <a class="header-anchor" href="#managing-labs" aria-label="Permalink to &quot;Managing Labs&quot;">​</a></h2><p>Running Labs reserve CPU, memory, GPU, and volume attachments in the cluster. Stop Labs when you no longer need the running process.</p><p>Some deployments stop idle JupyterLab servers automatically, which is called notebook culling. This is a deployment setting, not guaranteed behavior. VS Code, RStudio, OpenCode, and custom notebook images may detect idle time differently, depending on the installed controllers and images.</p><p>Common lifecycle operations:</p><ul><li><strong>Stop</strong> and <strong>Start</strong>: Stop deletes the Lab pod and releases compute resources; Start creates it again from the same configuration. Files on mounted persistent volumes remain.</li><li><strong>Delete</strong>: removes the Lab server object and pod. Mounted volumes are not necessarily deleted with it; delete unused volumes separately when you no longer need the data.</li><li><strong>Edit</strong>: changes the image, compute resources, volumes, configurations, or security options of an existing Lab. A running Lab restarts to apply the change, so save your work first: files outside mounted volumes are lost.</li><li><strong>Recreate</strong>: for changes that Edit does not cover, such as the Lab name or type, create a new Lab. To keep your home directory, attach the old Lab&#39;s persistent volume to the new one.</li></ul><p>Avoid customizing a running Lab by hand for anything you need to reproduce. If a team needs a repeatable environment, build a <a href="./custom_notebooks.html">Custom Notebook</a> image instead.</p><h3 id="advanced-configuration" tabindex="-1">Advanced Configuration <a class="header-anchor" href="#advanced-configuration" aria-label="Permalink to &quot;Advanced Configuration&quot;">​</a></h3><p>The <code>Configurations</code> and <code>Security options</code> fields are administrator-provided options for the Lab pod. Which options are available depends on the installation.</p><p>For example, GPU-specific workloads may use an affinity configuration so that the Lab is scheduled on nodes with the required GPU type. If the required option is not visible in the launch dialog, ask your platform administrator.</p><p>Configurations can also expose selected Kubernetes Secret values as environment variables. Create the secret in the workspace first, for example through <strong>K8s Secrets</strong> in the prokube user menu, then select the matching configuration when launching the Lab. Do not put secret values directly into notebooks, shell history, or container images.</p><p>Administrators create these options with Kubeflow PodDefaults or equivalent notebook configuration. Users can select only the configurations exposed to the workspace. If a configuration you need is missing, ask the platform administrator to add a reusable configuration instead of editing generated notebook resources by hand.</p><h2 id="persistence-and-package-installation" tabindex="-1">Persistence and Package Installation <a class="header-anchor" href="#persistence-and-package-installation" aria-label="Permalink to &quot;Persistence and Package Installation&quot;">​</a></h2><p>Files in the Lab home directory are backed by the workspace <a href="https://kubernetes.io/docs/concepts/storage/persistent-volumes/" target="_blank" rel="noreferrer">persistent volume</a> and survive Lab restarts. In the default images this is the <code>jovyan</code> user&#39;s home directory, usually <code>/home/jovyan</code>. This is the right place for notebooks, source code, configuration files, and cloned repositories.</p><p>Changes outside mounted volumes are temporary. Whenever the Lab pod is recreated, including when you stop and start or edit the Lab, system-level Python and OS packages and running background processes are lost.</p><p>For additional packages, prefer installs that write into the persistent home directory or project directory:</p><ul><li>use pip&#39;s <a href="https://pip.pypa.io/en/stable/user_guide/#user-installs" target="_blank" rel="noreferrer">user install mode</a>, for example <code>pip install --user</code>, for simple Python additions, provided the active Python environment loads user-site packages (isolated virtual environments usually do not);</li><li>use <a href="https://docs.astral.sh/uv/concepts/projects/config/#project-environment-path" target="_blank" rel="noreferrer">uv project environments</a> under the persistent workspace, for example the default <code>.venv</code> next to your project;</li><li>use <a href="https://python-poetry.org/docs/configuration/#virtualenvsin-project" target="_blank" rel="noreferrer">Poetry in-project virtual environments</a> when working with Poetry projects;</li><li>use <a href="https://docs.conda.io/projects/conda/en/latest/user-guide/tasks/manage-environments.html#specifying-a-location-for-an-environment" target="_blank" rel="noreferrer">conda environments with an explicit prefix</a>, for example under <code>/home/jovyan/envs</code> or your project directory.</li></ul><p>Keep dependency files such as <code>requirements.txt</code>, <code>pyproject.toml</code>, <code>environment.yml</code>, or <code>renv.lock</code> with your project. For team workflows or system-level dependencies, create a <a href="./custom_notebooks.html">Custom Notebook</a> image.</p><p>For large datasets, shared artifacts, pipeline outputs, and model files, prefer S3-compatible file storage over the workspace volume. Workspace volumes are useful for interactive work, but S3-backed storage is the better integration point for pipelines, MLflow, and model serving. For a platform-wide comparison, see <a href="./../platform/file_storage.html">File Storage</a>.</p><p>The default storage class is commonly <code>ReadWriteOnce</code>: in multi-node clusters, a volume can usually be mounted read-write only by pods on one node at a time. Do not use the same workspace volume from multiple running Labs at the same time unless your administrator has designed the storage setup for that pattern. For shared datasets and artifacts, use S3-compatible file storage or a storage class with the required access mode.</p><h2 id="installing-tools-without-root" tabindex="-1">Installing Tools Without Root <a class="header-anchor" href="#installing-tools-without-root" aria-label="Permalink to &quot;Installing Tools Without Root&quot;">​</a></h2><p>Labs usually run without root access. Install additional command-line tools into the persistent home directory when the selected image does not already include them.</p><p>One option is <a href="https://docs.brew.sh/Homebrew-on-Linux" target="_blank" rel="noreferrer">Homebrew on Linux</a>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HOMEBREW_PREFIX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.linuxbrew&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOMEBREW_PREFIX</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Homebrew/brew/tarball/master</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --strip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOMEBREW_PREFIX</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;export HOMEBREW_PREFIX=&quot;$HOME/.linuxbrew&quot;&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.bashrc</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;export PATH=&quot;$HOMEBREW_PREFIX/bin:$HOMEBREW_PREFIX/sbin:$PATH&quot;&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.bashrc</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOMEBREW_PREFIX</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/bin:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOMEBREW_PREFIX</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/sbin:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PATH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre></div><p>After that, install tools into your home directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jq</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> htop</span></span></code></pre></div><p>The installation lives under <code>/home/jovyan</code> in the default images and survives Lab restarts. For team-wide or production environments, move required tools into a <a href="./custom_notebooks.html">Custom Notebook</a> image instead.</p><p>For Node.js workflows, use a user-space version manager such as <a href="https://github.com/nvm-sh/nvm" target="_blank" rel="noreferrer">nvm</a> so the installation lives in the persistent home directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o-</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/nvm-sh/nvm/v0.39.7/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> NVM_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.nvm&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$NVM_DIR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/nvm.sh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ] &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$NVM_DIR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/nvm.sh&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nvm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span></span></code></pre></div><p>If you need the same Node.js version for a team workflow, prefer a custom image with the runtime pinned and tested.</p><h2 id="file-storage-from-labs" tabindex="-1">File Storage from Labs <a class="header-anchor" href="#file-storage-from-labs" aria-label="Permalink to &quot;File Storage from Labs&quot;">​</a></h2><p>Labs can work with S3-compatible file storage. The available tools depend on the selected image and workspace configuration.</p><p>The prokube-maintained <code>pk-*</code> notebook images include <code>rclone</code> with a preconfigured <code>minio</code> remote when the workspace file-storage configuration is available. Use it from a Lab terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rclone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lsd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minio:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rclone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> copy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minio:my-bucket/path/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rclone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> copy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minio:my-bucket/path/file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./file</span></span></code></pre></div><p>See <a href="./../platform/file_storage.html">File Storage</a> for S3-backed and PVC-backed storage. It has Python and R examples with <code>s3fs</code> and pandas, connection settings for external clients, and storage security notes.</p><h2 id="building-container-images" tabindex="-1">Building Container Images <a class="header-anchor" href="#building-container-images" aria-label="Permalink to &quot;Building Container Images&quot;">​</a></h2><p>You can build container images from a Lab and push them to a registry.</p><p>The build does not run in the Lab pod, and there is no local Docker daemon. The Docker client and Buildx plugin in the image send the build to a remote <a href="https://github.com/moby/buildkit" target="_blank" rel="noreferrer">BuildKit</a> service in the cluster. The <code>BUILDKIT_HOST</code> environment variable points to this service when the cluster provides it.</p><p>This tooling is included in the prokube-maintained <code>pk-*</code> notebook images, which are based on the upstream Kubeflow notebook server images. That covers the standard prokube JupyterLab, VS Code (code-server), and RStudio images. Upstream or fully custom images support builds only if they include the same tooling and startup configuration.</p><p>Push every build to a registry:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">registr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> buildx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">registr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">imag</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ta</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>Always use <code>--push</code>. The Lab pod has no local image store, so the built image is only usable from the registry.</p><p>In prokube-maintained images, <code>docker build</code> may be wrapped to call <code>docker buildx build</code>, so existing scripts and Makefiles work with the remote builder.</p><p>For multi-architecture images, pass the target platforms explicitly and push the manifest list:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> buildx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --platform</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux/amd64,linux/arm64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">registr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">imag</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ta</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>Run <code>docker login</code> in your Lab before pushing. The builder does not share your registry credentials with other users. If platform workloads later need to pull the private image, add pull credentials to the workspace. See <a href="./../platform/kubernetes.html#registry-credentials">Registry Credentials</a>.</p><p>The remote builder caches build layers to speed up later builds. The cache is not a registry, so do not rely on it to keep images.</p><div class="warning custom-block"><p class="custom-block-title">The builder is shared across workspaces</p><p>All workspaces in the cluster use the same BuildKit service, and workspace boundaries do not apply to it:</p><ul><li>Build history and build logs, including build arguments, image names, and push targets, can be listed and read from any workspace.</li><li>Layer caches and cache mounts (<code>RUN --mount=type=cache</code>) are shared between all users&#39; builds. Another build that uses the same cache mount ID can read and change its contents.</li><li>Base images pulled with your registry credentials can stay in the cache and be reused by other users&#39; builds.</li></ul><p>Do not put secrets into build arguments, Dockerfile instructions, or build output. Pass build-time credentials with <code>docker buildx build --secret</code>, which keeps their values out of the cache and the build history. Do not use the shared builder for source code, logs, or images that must stay hidden from other platform users.</p></div><p>This setup is only for building and pushing images. It is not a container runtime: images cannot be started with <code>docker run</code> inside the Lab. Run workloads through Kubernetes resources, pipelines, model serving, or other platform runtimes instead.</p><h2 id="troubleshooting-labs" tabindex="-1">Troubleshooting Labs <a class="header-anchor" href="#troubleshooting-labs" aria-label="Permalink to &quot;Troubleshooting Labs&quot;">​</a></h2><p>Start with the Lab details page and the pod events. Most startup failures show up as Kubernetes events before they show up in the application UI.</p><p>If you have Kubernetes access, inspect the pod directly:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> describe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pod</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pod-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">workspac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pod-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">workspac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all-containers</span></span></code></pre></div><p>Common cases:</p><ul><li><strong>The Lab does not start</strong>: check pod events for image pull errors, missing secrets, failed volume mounts, resource quota limits, or scheduling errors.</li><li><strong>The browser shows an upstream connection error</strong>: the Lab pod may not be ready yet, may have crashed, or may be unable to start the expected web server. Check pod status and logs.</li><li><strong>The Lab starts and then crashes</strong>: use the <a href="./../platform/observability.html#logs-browser">Logs browser</a> to search the Lab pod logs by workspace and pod name.</li><li><strong>A private custom image cannot be pulled</strong>: verify the image reference and registry credentials. See <a href="./custom_notebooks.html#registry-credentials">Registry Credentials</a>.</li><li><strong>A volume cannot be attached</strong>: another running pod may still be using a <code>ReadWriteOnce</code> volume on a different node, or the cluster may still have a stale volume attachment after a node restart. Stop other Labs using the volume and contact your administrator if the attachment does not clear. Do not delete <code>VolumeAttachment</code> resources yourself unless you administer the cluster and have verified the stale attachment.</li><li><strong>The Lab needs more CPU, memory, or GPU</strong>: change the compute resources with <strong>Edit</strong>. If the volume itself is too small, create or request a larger volume and copy the data.</li><li><strong>A deleted Lab leaves data behind</strong>: this is expected for persistent volumes. Delete unused volumes separately when you no longer need them.</li><li><strong>A Lab server object or pod appears stuck</strong>: check events first. If a pod remains after deleting the Lab, ask an administrator or use <code>kubectl</code> only if you understand which pod belongs to the Lab.</li></ul>`,76)])])}const u=s(n,[["render",o]]);export{c as __pageData,u as default};
